  "engines": {
    "node": ">=22.12.0"
  },
  "dependencies": {
    "pathe": "^2.0.3",
    "@tanstack/react-router": "1.170.15",
    "@tanstack/react-start-client": "1.168.13",
    "@tanstack/react-start-rsc": "0.1.24",
    "@tanstack/react-start-server": "1.167.19",
    "@tanstack/router-utils": "1.162.2",
    "@tanstack/start-client-core": "1.170.12",
